//! 🧪️ Ranked insert/remove preserves original reader identity and agrees with independent SQL order.
use super::*;
use super::super::tests::{grant,observe,original,close_source,row,list};
fn close(plan:&mut PersistentSplice<i64>){plan.begin_close();for turn in 0..10000{if plan.terminal_is_empty(){return;}let g=grant(plan.close_demand(4096).unwrap());let(s,h)=observe(||plan.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(s.progress()!=Default::default()||plan.terminal_is_empty(),"splice close inert: {g:?}");assert!(turn<9999);}}
mod quick{
use super::*;
/// 🧫️ Neutral empty, split, partial-interior and removal vectors conserve immutable row authorities.
#[test]
fn persistent_ranked_splice_matches_order_and_preserves_original_readers(){let cases:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for case in cases.as_array().unwrap(){let values:Vec<_>=case["before"].as_array().unwrap().iter().map(|v|v.as_i64().unwrap()).collect();let mut base=original(if values.is_empty(){PersistentList::default()}else{let rows=std::array::from_fn(|i|values.get(i).map(|v|row(*v)));if values.len()<=16{PersistentList::admit_leaf(rows,values.len(),grant(PersistentList::<i64>::page_birth_demand())).unwrap_or_else(|_|panic!("original leaf")).0}else{let first=PersistentList::admit_leaf(rows,16,grant(PersistentList::<i64>::page_birth_demand())).unwrap_or_else(|_|panic!("first original leaf")).0;let last=PersistentList::admit_leaf(std::array::from_fn(|i|values.get(16+i).map(|v|row(*v))),values.len()-16,grant(PersistentList::<i64>::page_birth_demand())).unwrap_or_else(|_|panic!("last original leaf")).0;let mut children=std::array::from_fn(|_|None);children[0]=Some(first);children[1]=Some(last);PersistentList::admit_branch(children,grant(PersistentList::<i64>::page_birth_demand())).unwrap_or_else(|_|panic!("original branch")).0}});let mut authored=original(row(case["authored"].as_i64().unwrap_or(0)));let insert=case["kind"]=="insert";let index=case["index"].as_u64().unwrap()as usize;let mut plan=PersistentSplice::new(if insert{PersistentSpliceKind::Insert}else{PersistentSpliceKind::Remove},index);
 for turn in 0..1000{let a=insert.then(||authored.borrow());let g=grant(plan.demand(base.borrow(),a).unwrap());let(s,h)=observe(||plan.advance(base.borrow(),a,Default::default()).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));let(s,h)=observe(||plan.advance(base.borrow(),a,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedCloneStep::Complete(_)){break;}assert!(turn<999);}
 let(candidate,p)=plan.take(grant(plan.take_demand())).unwrap().unwrap();assert_eq!(p.retained_capacity_bytes,0);let expected:Vec<_>=case["expected"].as_array().unwrap().iter().map(|v|v.as_i64().unwrap()).collect();assert_eq!((0..candidate.len()).map(|i|*candidate.get(i).unwrap()).collect::<Vec<_>>(),expected,"{}",case["id"]);assert_eq!((0..base.borrow().get().len()).map(|i|*base.borrow().get().get(i).unwrap()).collect::<Vec<_>>(),values);for pos in 0..candidate.len(){if insert&&pos==index{continue;}let old=if insert{pos-usize::from(pos>index)}else{pos+usize::from(pos>=index)};assert_eq!(candidate.get(pos).unwrap()as*const i64,base.borrow().get().get(old).unwrap()as*const i64);}
 let mut candidate=original(candidate);close(&mut plan);close_source(&mut candidate);close_source(&mut authored);close_source(&mut base);eprintln!("[DEBUG] immutable ranked splice {:?}: old readers unchanged, expected order, unchanged row authorities shared",case["id"]);
}}
/// 🛑️ Split and ancestor cancellation cuts keep the unchanged original source alive.
#[test]
fn persistent_ranked_splice_cancels_split_and_ancestor_frontiers(){for cut in[0,1,2,3,5,10,20,30,40,50]{let mut base=original(list(17));let mut authored=original(row(-7));let mut plan=PersistentSplice::new(PersistentSpliceKind::Insert,8);for _ in 0..cut{let g=grant(plan.demand(base.borrow(),Some(authored.borrow())).unwrap());if matches!(plan.advance(base.borrow(),Some(authored.borrow()),g).unwrap(),RetainedCloneStep::Complete(_)){break;}}assert_eq!(base.borrow().get().get(8),Some(&16));close(&mut plan);close_source(&mut authored);close_source(&mut base);}}
}
